const now = new Date();
const isoDate = now.toISOString().slice(0, 10);
const seed = Math.floor(now.getTime() / 86400000);
const topicCatalog = [
  {
    canonicalTopic: 'how semiconductor supply chains became geopolitical leverage',
    audienceAngle: 'systems and power',
    subNiche: 'technology-history'
  },
  {
    canonicalTopic: 'the hidden decisions behind the manhattan project',
    audienceAngle: 'science and state power',
    subNiche: 'history-science'
  },
  {
    canonicalTopic: 'why recommendation algorithms shape modern culture',
    audienceAngle: 'internet systems',
    subNiche: 'technology-society'
  },
  {
    canonicalTopic: 'the error chains that changed modern medicine',
    audienceAngle: 'scientific breakthroughs',
    subNiche: 'science-history'
  },
  {
    canonicalTopic: 'how undersea cables quietly hold up the internet',
    audienceAngle: 'infrastructure and hidden systems',
    subNiche: 'internet-history'
  },
  {
    canonicalTopic: 'the industrial race that made chips the new oil',
    audienceAngle: 'industry and strategy',
    subNiche: 'future-industries'
  }
];
const chosenTopic = topicCatalog[Math.abs(seed) % topicCatalog.length];
return [{
  json: {
    run: {
      id: `run-${isoDate}`,
      date: isoDate,
      status: 'draft',
      triggerSource: $execution.mode || 'manual'
    },
    channel: {
      slug: 'the-hidden-thread',
      name: 'The Hidden Thread',
      language: 'en',
      timezone: 'Europe/Madrid',
      tone: 'calm-premium-documentary',
      identity: {
        avatarConcept: 'Editorial monogram HT in ivory serif on deep petrol background',
        bannerConcept: 'Minimal timeline line, The Hidden Thread wordmark, subtitle History, Science, and Technology Explained',
        thumbnailStyle: 'High-contrast editorial, one dominant idea, 3-5 words max, no AI-glow, no clutter',
        palette: ['#0F1720', '#D9D2C3', '#8C6A43'],
        typeSystem: ['Cormorant Garamond', 'Libre Baskerville', 'Manrope']
      }
    },
    niche: {
      key: 'history-science-technology-documentaries',
      label: 'History, science and technology documentary essays',
      audience: 'Adults who like documentary storytelling, systems thinking and clear explanations',
      premise: 'Explain how decisions, systems and unintended consequences shape the modern world.'
    },
    config: {
      targetMinutes: 38,
      publishHourLocal: '18:00',
      llm: {
        provider: 'openai',
        model: 'gpt-4.1'
      },
      voiceover: {
        provider: 'elevenlabs',
        model: 'eleven_v3',
        voiceStyle: 'authoritative, warm, controlled, cinematic'
      },
      music: {
        provider: 'elevenlabs-music',
        model: 'music_v1',
        targetStyle: 'instrumental documentary underscore with subtle tension and no vocals',
        mix: {
          targetVolumePercent: 18,
          duckingPercentUnderVoice: 70,
          fadeInSeconds: 2,
          fadeOutSeconds: 3
        }
      },
      subtitles: {
        provider: 'openai-stt',
        mode: 'word-level',
        style: 'kinetic-documentary',
        alwaysVisible: true
      },
      visuals: {
        renderProvider: 'creatomate',
        scenesPerChapter: 8,
        chapterCards: true,
        lowerThirds: true,
        motionProfile: 'subtle pans, slow zooms, elegant fades, restrained transitions',
        visualMix: {
          motionGraphics: 0.35,
          archiveStill: 0.20,
          aiImage: 0.20,
          heroAiVideo: 0.15,
          mapsAndCharts: 0.10
        }
      },
      delivery: {
        mode: 'b2_manual_publish',
        objectPrefixNaming: 'YYYY-MM-DD/episode-slug/',
        requiredFiles: ['video.mp4', 'thumbnail.png', 'title.txt', 'description.txt', 'tags.json', 'chapters.txt', 'subtitles.srt', 'publication-checklist.md'],
        manualUploadRequired: true
      },
      editorialPolicy: {
        forbiddenRepeatWindowDays: 180,
        minimumOriginalityScore: 85,
        requireFreshAngle: true,
        requireTransformativeNarrative: true,
        requireMonetizationSafeScript: true
      }
    },
    workingTopic: {
      canonicalTopic: chosenTopic.canonicalTopic,
      angle: chosenTopic.audienceAngle,
      subNiche: chosenTopic.subNiche,
      uniquenessHash: chosenTopic.canonicalTopic.replace(/[^a-z0-9]+/g, '-'),
      chosenBy: 'rotation-seed-mock'
    },
    prompts: {
      researchSystem: 'You are a senior documentary researcher for a premium YouTube longform channel. Return valid JSON only. Focus on causality, originality and strong retention hooks.',
      researchUser: `Prepare a research pack for a 38 minute documentary about ${chosenTopic.canonicalTopic}. Avoid generic listicle angles. Return fresh angle, source plan, factual checkpoints, retention hooks and monetization risks.`,
      outlineSystem: 'You are a head of story for premium faceless documentaries. Return valid JSON only. Build a retention-aware structure with chapters and open loops.',
      scriptSystem: 'You are a lead writer for premium English YouTube documentaries. Return valid JSON only. The script must sound native, calm, clear, analytical and monetization-safe.'
    },
    integrations: {
      researchLlmEnabled: false,
      outlineLlmEnabled: false,
      scriptLlmEnabled: false,
      voiceoverEnabled: false,
      musicEnabled: false,
      subtitleAlignmentEnabled: false,
      renderEnabled: false,
      b2DeliveryEnabled: false
    }
  }
}];

const data = $input.first().json;
const editorialChecks = {
  nicheLocked: true,
  languageLocked: data.channel.language === 'en',
  duplicateCheckImplementedInDb: false,
  requiresDbQuery: ['editorial_topics', 'content_runs'],
  forbiddenRepeatWindowDays: data.config.editorialPolicy.forbiddenRepeatWindowDays,
  originalityScoreTarget: data.config.editorialPolicy.minimumOriginalityScore,
  bannedPatterns: [
    'top 10 facts',
    'generic timeline recap',
    'video without angle',
    'obvious AI filler'
  ]
};
const monetizationChecklist = {
  noCopyrightUnsafeMusic: true,
  noUnlicensedThirdPartyFootage: true,
  noMedicalOrLegalAdviceFraming: true,
  noGraphicShockHooks: true,
  requireTransformativeCommentary: true,
  requireManualFinalReviewBeforeUpload: true
};
return [{ json: { ...data, editorialChecks, monetizationChecklist } }];

const data = $input.first().json;
const raw = data.output?.[0]?.content?.[0]?.text || data.body?.output_text || data.body?.choices?.[0]?.message?.content;
let research = null;
if (raw) {
  try { research = JSON.parse(raw); } catch (error) { research = null; }
}
if (!research) {
  research = {
    canonicalTopic: data.workingTopic.canonicalTopic,
    freshAngle: `Treat ${data.workingTopic.canonicalTopic} as a chain of hidden decisions, incentives and consequences rather than a simple chronology.`,
    sourcePlan: ['books and academic history', 'serious journalism', 'industry reports', 'primary-source timelines'],
    factualCheckpoints: [
      'verify key dates and names',
      'verify what is disputed versus established',
      'verify modern relevance with current sources'
    ],
    retentionHooks: [
      'open with a modern consequence',
      'end each chapter with an unresolved pressure point',
      'alternate human motives and system-level effects'
    ],
    monetizationRisks: ['graphic wartime imagery', 'speculative claims without sourcing'],
    originalityNotes: 'Angle is causal and systems-focused, not listicle-based.'
  };
}
return [{ json: { ...data, research } }];

const data = $input.first().json;
const raw = data.output?.[0]?.content?.[0]?.text || data.body?.output_text || data.body?.choices?.[0]?.message?.content;
let outline = null;
if (raw) {
  try { outline = JSON.parse(raw); } catch (error) { outline = null; }
}
if (!outline) {
  const chapterTitles = [
    'The promise of the system',
    'The hidden context everyone skips',
    'The first decisive break',
    'Why the key actors chose this path',
    'The errors that changed everything',
    'How the system spread into everyday life',
    'The modern consequence most people miss',
    'What this means next'
  ];
  outline = {
    workingTitle: `The hidden story of ${data.workingTopic.canonicalTopic}`,
    hook: 'What looks inevitable today usually began with a few decisions nobody expected to matter this much.',
    promise: `By the end, you will understand ${data.workingTopic.canonicalTopic} as a connected story of choices, pressure and consequences.`,
    cta: 'Subscribe for more longform documentary essays on history, science and technology.',
    chapters: chapterTitles.map((title, index) => ({
      chapterIndex: index + 1,
      title,
      objective: `Advance the narrative with a new causal layer in ${title.toLowerCase()}.`,
      targetMinutes: index === 0 ? 4 : 4.8,
      retentionDevice: index % 2 === 0 ? 'open-loop' : 'reveal'
    }))
  };
}
return [{ json: { ...data, outline } }];

const data = $input.first().json;
const raw = data.output?.[0]?.content?.[0]?.text || data.body?.output_text || data.body?.choices?.[0]?.message?.content;
let script = null;
if (raw) {
  try { script = JSON.parse(raw); } catch (error) { script = null; }
}
if (!script) {
  script = {
    title: `The Hidden Story of ${data.workingTopic.canonicalTopic}`,
    description: `A premium longform documentary essay explaining ${data.workingTopic.canonicalTopic} through the decisions, systems and consequences that shaped it.`,
    tags: ['history documentary', 'science documentary', 'technology documentary', 'documentary essay', 'systems history', 'the hidden thread'],
    thumbnailHypothesis: 'One powerful concept, one strong phrase, one symbolic object',
    intro: `${data.outline.hook} In this documentary, we are following the hidden chain from origin to modern impact.`,
    chapters: data.outline.chapters.map((chapter) => ({
      chapterIndex: chapter.chapterIndex,
      title: chapter.title,
      narration: `${chapter.title}. This section explains the context, the pressure on the actors involved, the decision they made, and why it still matters now.`
    })),
    outro: data.outline.cta,
    monetizationSafety: {
      advertiserFriendly: true,
      factualClaimsRequireReview: true,
      avoidShockLanguage: true,
      avoidUnlicensedQuotesOrFootage: true
    }
  };
}
return [{ json: { ...data, script } }];

const data = $input.first().json;
const scenes = [];
let sceneIndex = 1;
for (const chapter of data.outline.chapters) {
  for (let i = 0; i < data.config.visuals.scenesPerChapter; i++) {
    const visualType = i % 6 === 0
      ? 'hero_ai_video'
      : i % 5 === 0
        ? 'maps_and_charts'
        : i % 3 === 0
          ? 'motion_graphic'
          : i % 2 === 0
            ? 'archive_still'
            : 'ai_image';
    scenes.push({
      sceneIndex,
      chapterIndex: chapter.chapterIndex,
      chapterTitle: chapter.title,
      visualType,
      searchText: `${data.workingTopic.canonicalTopic} ${chapter.title}`,
      motionPreset: 'slow-pan-or-push',
      transitionStyle: 'elegant-fade',
      subtitleStyle: data.config.subtitles.style,
      targetDurationSeconds: Math.round((chapter.targetMinutes * 60) / data.config.visuals.scenesPerChapter)
    });
    sceneIndex += 1;
  }
}
const assetPlan = scenes.map((scene) => ({
  sceneIndex: scene.sceneIndex,
  provider: scene.visualType === 'hero_ai_video' ? 'runway' : (scene.visualType === 'maps_and_charts' ? 'internal-graphics' : 'image-or-archive-layer'),
  requestedType: scene.visualType,
  query: scene.searchText
}));
return [{ json: { ...data, scenes, assetPlan } }];

const data = $input.first().json;
const subtitleSegments = [];
let segmentIndex = 1;
for (const chapter of data.outline.chapters) {
  subtitleSegments.push({
    segmentIndex,
    startMs: (segmentIndex - 1) * 4500,
    endMs: (segmentIndex - 1) * 4500 + 3400,
    text: chapter.title,
    emphasisWords: [chapter.title.split(' ')[0] || chapter.title],
    style: data.config.subtitles.style
  });
  segmentIndex += 1;
}
return [{ json: { ...data, subtitleSegments } }];

const data = $input.first().json;
const thumbnailPackage = {
  channelName: data.channel.name,
  style: data.channel.identity.thumbnailStyle,
  visualConcept: `A single symbolic image representing ${data.workingTopic.canonicalTopic}, with strong negative space and premium editorial contrast.`,
  shortTextOptions: [
    'THE HIDDEN COST',
    'WHY IT CHANGED',
    'THE SYSTEM BENEATH'
  ],
  avoid: ['busy collages', 'AI glow', 'tiny text', 'fake faces', 'generic cyberpunk colors']
};
return [{ json: { ...data, thumbnailPackage } }];

const data = $input.first().json;
const slug = (data.script?.title || data.workingTopic.canonicalTopic).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const chaptersText = data.outline.chapters.map((chapter, index) => `${index + 1}. ${chapter.title}`).join('\n');
const objectPrefix = `${data.run.date}/${slug}/`;
const delivery = {
  bucketName: 'set-in-b2-credentials-or-config',
  objectPrefix,
  reviewMode: 'manual-before-youtube',
  files: [
    { key: `${objectPrefix}video.mp4`, name: 'video.mp4', role: 'final-video' },
    { key: `${objectPrefix}thumbnail.png`, name: 'thumbnail.png', role: 'thumbnail' },
    { key: `${objectPrefix}title.txt`, name: 'title.txt', role: 'metadata', content: data.script.title },
    { key: `${objectPrefix}description.txt`, name: 'description.txt', role: 'metadata', content: data.script.description },
    { key: `${objectPrefix}tags.json`, name: 'tags.json', role: 'metadata', content: JSON.stringify(data.script.tags, null, 2) },
    { key: `${objectPrefix}chapters.txt`, name: 'chapters.txt', role: 'metadata', content: chaptersText },
    { key: `${objectPrefix}subtitles.srt`, name: 'subtitles.srt', role: 'captions' },
    { key: `${objectPrefix}publication-checklist.md`, name: 'publication-checklist.md', role: 'qa', content: '- Review title\n- Review thumbnail\n- Review music mix\n- Review factual claims\n- Upload manually to YouTube' }
  ]
};
return [{ json: { ...data, delivery } }];

const data = $input.first().json;
const issues = [];
if (!data.niche?.key) issues.push('No niche selected');
if (!data.research?.freshAngle) issues.push('Missing documentary angle');
if (!data.outline?.chapters?.length) issues.push('Missing outline');
if (!data.script?.chapters?.length) issues.push('Missing chapter script');
if ((data.scenes || []).length < 50) issues.push('Too few scenes for a 38 minute documentary');
if (!(data.subtitleSegments || []).length) issues.push('Missing subtitles');
if (data.integrations.researchLlmEnabled === false) issues.push('Research integration not connected');
if (data.integrations.scriptLlmEnabled === false) issues.push('Script integration not connected');
if (data.integrations.voiceoverEnabled === false) issues.push('Voiceover integration not connected');
if (data.integrations.musicEnabled === false) issues.push('Background music integration not connected');
if (data.integrations.subtitleAlignmentEnabled === false) issues.push('Subtitle alignment not connected');
if (data.integrations.renderEnabled === false) issues.push('Render integration not connected');
if (data.integrations.b2DeliveryEnabled === false) issues.push('Backblaze B2 delivery not connected');
const deliveryManifest = {
  channelName: data.channel.name,
  channelIdentity: data.channel.identity,
  title: data.script?.title || `The Hidden Story of ${data.workingTopic.canonicalTopic}`,
  description: data.script?.description || `Documentary essay about ${data.workingTopic.canonicalTopic}.`,
  tags: data.script?.tags || [],
  bucketName: data.delivery.bucketName,
  objectPrefix: data.delivery.objectPrefix,
  deliveryMode: data.config.delivery.mode,
  manualUpload: true
};
const fullyIntegrated = Object.values(data.integrations).every(Boolean);
const assessment = {
  currentWorkflowWillGenerateProfessionalVideo: fullyIntegrated,
  currentWorkflowIsMonetizableAsIs: fullyIntegrated,
  reasonsIfNotReady: fullyIntegrated ? [] : [
    'The current base is structurally correct but still uses placeholders for key providers.',
    'A premium result depends on real OpenAI writing, ElevenLabs voice, Eleven Music background score, Creatomate rendering and Backblaze B2 delivery.',
    'Manual editorial review remains required before YouTube upload.'
  ]
};
const status = issues.length ? 'needs_review' : 'ready_for_delivery';
return [{ json: { ...data, deliveryManifest, quality: { issues, status }, assessment } }];
